package org.eclipse.rdf4j.workbench.commands;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;

import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.federated.FedXFactory;
import org.eclipse.rdf4j.federated.endpoint.EndpointFactory;
import org.eclipse.rdf4j.model.vocabulary.RDFS;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.manager.RepositoryManager;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.memory.MemoryStore;
import org.eclipse.rdf4j.workbench.support.TestServletConfig;
import org.eclipse.rdf4j.workbench.util.WorkbenchPageProtocol;
import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;

import tools.jackson.databind.JsonNode;
import tools.jackson.databind.ObjectMapper;

class ExploreFederationTest {

	private static final ObjectMapper JSON = new ObjectMapper();

	@Test
	void duplicateMemberQuadsAndSummaryValuesHaveMatchingDistinctCounts() throws Exception {
		SailRepository first = new SailRepository(new MemoryStore());
		SailRepository second = new SailRepository(new MemoryStore());
		first.init();
		second.init();
		var factory = first.getValueFactory();
		var resource = factory.createIRI("urn:test:resource");
		var predicate = factory.createIRI("urn:test:predicate");
		var object = factory.createIRI("urn:test:object");
		var graph = factory.createIRI("urn:test:graph");
		for (SailRepository member : List.of(first, second)) {
			try (RepositoryConnection connection = member.getConnection()) {
				connection.add(resource, predicate, object);
				connection.add(resource, predicate, object, graph);
				connection.add(resource, RDFS.SUBCLASSOF, object);
				connection.add(resource, RDFS.SUBCLASSOF, object, graph);
			}
		}
		var federation = FedXFactory.newFederation()
				.withMembers(List.of(EndpointFactory.loadEndpoint("first", first),
						EndpointFactory.loadEndpoint("second", second)))
				.create();
		federation.init();
		ExploreServlet servlet = new ExploreServlet();
		servlet.setRepository(federation);
		servlet.setRepositoryManager(mock(RepositoryManager.class));
		servlet.init(TestServletConfig.withParams("explore", "cookie-max-age", "300"));
		try {
			List<JsonNode> roles = request(servlet, "outgoing", "rows", null);
			assertThat(metadata(roles).path("explore-graph-mode").asText()).isEqualTo("dataset");
			assertThat(rows(roles)).hasSize(4);
			assertThat(count(servlet, "outgoing", "default")).isEqualTo("2");
			assertThat(count(servlet, "outgoing", "named")).isEqualTo("2");
			assertThat(rows(request(servlet, "superClasses", "rows", null))).hasSize(1);
			assertThat(count(servlet, "superClasses", null)).isEqualTo("1");
		} finally {
			servlet.destroy();
			federation.shutDown();
			first.shutDown();
			second.shutDown();
		}
	}

	private static String count(ExploreServlet servlet, String section, String scope) throws Exception {
		return metadata(request(servlet, section, "count", scope)).path("explore-count").asText();
	}

	private static List<JsonNode> request(ExploreServlet servlet, String section, String kind, String scope)
			throws Exception {
		MockHttpServletRequest request = new MockHttpServletRequest("GET", "/explore");
		request.addHeader("Accept", WorkbenchPageProtocol.ACCEPT);
		request.addParameter("resource", "<urn:test:resource>");
		request.addParameter("section", section);
		request.addParameter("kind", kind);
		if (scope != null) {
			request.addParameter("scope", scope);
		}
		MockHttpServletResponse response = new MockHttpServletResponse();
		servlet.service(request, response);
		List<JsonNode> result = response.getContentAsString().lines().map(JSON::readTree).toList();
		assertThat(result.getLast().path("type").asText()).as(response.getContentAsString()).isEqualTo("end");
		return result;
	}

	private static JsonNode metadata(List<JsonNode> records) {
		return records.stream()
				.filter(record -> "metadata".equals(record.path("type").asText()))
				.findFirst()
				.orElseThrow()
				.path("values");
	}

	private static List<JsonNode> rows(List<JsonNode> records) {
		List<JsonNode> rows = new ArrayList<>();
		for (JsonNode record : records) {
			if ("rows".equals(record.path("type").asText())) {
				record.path("values").forEach(rows::add);
			}
		}
		return rows;
	}
}
